<?php
namespace App\Support;
use App\Models\Appointment; use App\Models\Provider; use App\Models\Service; use App\Models\User;
final class ApiPresenter { public static function user(User $u): array { return ['id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'role'=>$u->role->value]; } public static function service(Service $s): array { $data=['id'=>$s->id,'name'=>$s->name,'description'=>$s->description,'duration_minutes'=>$s->duration_minutes,'is_active'=>$s->is_active]; if($s->relationLoaded('pivot')){$data['price']=$s->pivot->price;$data['provider_service_active']=(bool)$s->pivot->is_active;} return $data; } public static function provider(Provider $p): array { return ['id'=>$p->id,'name'=>$p->relationLoaded('user')?$p->user->name:null,'bio'=>$p->bio,'timezone'=>$p->timezone,'is_active'=>$p->is_active,'services'=>$p->relationLoaded('services')?$p->services->map(fn($s)=>self::service($s))->values():null]; } public static function appointment(Appointment $a): array { return ['id'=>$a->id,'provider_id'=>$a->provider_id,'service_id'=>$a->service_id,'starts_at'=>$a->starts_at?->utc()->toIso8601String(),'ends_at'=>$a->ends_at?->utc()->toIso8601String(),'duration_minutes'=>$a->duration_minutes,'price'=>$a->price,'currency'=>$a->currency,'status'=>$a->status->value,'hold_expires_at'=>$a->hold_expires_at?->utc()->toIso8601String(),'payment'=>$a->relationLoaded('payment')&&$a->payment?['id'=>$a->payment->id,'status'=>$a->payment->status->value,'provider'=>$a->payment->provider->value,'external_reference'=>$a->payment->external_reference]:null]; } }
